1	// Acceptance tests for the change request:
2	//   "Let me filter projects by active, on hold or finished."
3	//
4	// The projects page (projects-page, at /projects) lists every (live) project. Projects already carry
5	// a lifecycle STATUS — active, on hold or finished (the project-status feature). This change adds a
6	// control (project-status-filter) on the projects page that narrows that list to ONE status: pick a
7	// status and only the projects in that state remain — every other project is hidden. With nothing
8	// picked (the default) every project is still shown, exactly as before, so this is a pure narrowing
9	// on top of the existing list — mirroring the sibling invoice-status-filter / project-tag-filter.
10	//
11	// Asserts ONLY through the UI (data-testid). Data is arranged via resetAndSeed; the filter is driven
12	// through the project-status-filter control. Seed honours clients: { id, name, email } and
13	// projects: { id, clientId, name, status } — `status` seeds a project directly into one of the three
14	// states so the narrowing can be checked without a click.
15	//
16	// Statuses are seeded with the CANONICAL codes the schema stores ('ACTIVE' / 'ON_HOLD' / 'FINISHED',
17	// per Flyway V21 and the project form's option values) rather than free-text, because a FILTER must
18	// compare the project's stored status against the chosen one exactly — unlike the display, which is
19	// asserted tolerantly. The filter is a single control (one testid), so it is a <select> of the
20	// statuses: we do not assume the casing/wording of its option labels or values — for a wanted status
21	// we locate the option whose visible text OR value matches the status case-insensitively and select
22	// it by its own value, and to clear we select the "all" option (value === '' or an "all" label). So
23	// a correct implementation passes however it renders and values its status options.
24	//
25	// The fixture puts TWO projects at ACTIVE (1 and 4, under two different clients), one ON_HOLD (2) and
26	// one FINISHED (3). So narrowing to active must keep a SET (1 and 4, not a single hard-coded row) and
27	// drop the on-hold and finished ones; narrowing to on hold, then finished, flips to DISJOINT single
28	// sets — proving the control reads the chosen status rather than always filtering to one. Clearing
29	// brings every project back. This SHOULD FAIL before the change: there is no project-status-filter on
30	// the projects page today.
31	import { test, expect, type Page } from '@playwright/test';
32	import { resetAndSeed } from '../support/seed';
33	
34	// Two projects are ACTIVE (1, 4) and sit under different clients, so a genuine "narrow to active"
35	// keeps both while hiding the ON_HOLD (2) and the FINISHED (3). The three statuses form disjoint sets.
36	const FIXTURE = {
37	  clients: [
38	    { id: 1, name: 'Acme Corp', email: 'ops@acme.example' },
39	    { id: 2, name: 'Globex', email: 'hello@globex.example' },
40	  ],
41	  projects: [
42	    { id: 1, clientId: 1, name: 'Website redesign', status: 'ACTIVE' },
43	    { id: 2, clientId: 1, name: 'Warehouse automation', status: 'ON_HOLD' },
44	    { id: 3, clientId: 2, name: 'Mobile app', status: 'FINISHED' },
45	    { id: 4, clientId: 2, name: 'Billing portal', status: 'ACTIVE' },
46	  ],
47	};
48	
49	// The distinguishing token for each state. Mutually exclusive: ACTIVE carries only "active", ON_HOLD
50	// only "hold", FINISHED only "finish" — so each can be told apart from the other two, and from the
51	// "all" option (which reads "all"/"every", never one of these). Matches how project-status.spec and
52	// the invoice-stage specs assert status tolerantly.
53	const ACTIVE = /active/i;
54	const HOLD = /hold/i;
55	const FINISHED = /finish|complete|done/i;
56	
57	// The <option> value whose visible text OR value matches `status` (case-insensitive). Selecting by the
58	// option's own value keeps us agnostic to the label/value casing/wording the feature chose.
59	async function optionValueFor(page: Page, status: RegExp): Promise<string> {
60	  const value = await page
61	    .getByTestId('project-status-filter')
62	    .locator('option')
63	    .evaluateAll((opts, src) => {
64	      const re = new RegExp(src as string, 'i');
65	      const match = (opts as HTMLOptionElement[]).find(
66	        (o) => re.test((o.textContent ?? '').trim()) || re.test(o.value),
67	      );
68	      return match ? match.value : null;
69	    }, status.source);
70	  if (value === null) {
71	    throw new Error(`project-status-filter has no option matching ${status}`);
72	  }
73	  return value;
74	}
75	
76	// Narrow the list to a single status through the control.
77	async function narrowTo(page: Page, status: RegExp): Promise<void> {
78	  await page.getByTestId('project-status-filter').selectOption(await optionValueFor(page, status));
79	}
80	
81	// The "show every status" option: an empty value by convention, or an option labelled "all".
82	async function showAllStatuses(page: Page): Promise<void> {
83	  const value = await page
84	    .getByTestId('project-status-filter')
85	    .locator('option')
86	    .evaluateAll((opts) => {
87	      const match = (opts as HTMLOptionElement[]).find(
88	        (o) => o.value === '' || /all/i.test((o.textContent ?? '').trim()),
89	      );
90	      return match ? match.value : null;
91	    });
92	  if (value === null) {
93	    throw new Error('project-status-filter has no "all statuses" option');
94	  }
95	  await page.getByTestId('project-status-filter').selectOption(value);
96	}
97	
98	test.describe('filter projects by status', () => {
99	  test.beforeEach(async () => {
100	    await resetAndSeed(FIXTURE);
101	  });
102	
103	  test('with nothing picked, the filter is present and every project is shown', async ({ page }) => {
104	    await page.goto('/projects');
105	
106	    await expect(page.getByTestId('projects-page')).toBeVisible();
107	    await expect(page.getByTestId('project-status-filter')).toBeVisible();
108	
109	    // Default view: all four projects, across every status.
110	    await expect(page.getByTestId('project-row-1')).toBeVisible();
111	    await expect(page.getByTestId('project-row-2')).toBeVisible();
112	    await expect(page.getByTestId('project-row-3')).toBeVisible();
113	    await expect(page.getByTestId('project-row-4')).toBeVisible();
114	    await expect(page.locator('[data-testid^="project-row-"]')).toHaveCount(4);
115	  });
116	
117	  test('narrowing to active keeps only the active projects', async ({ page }) => {
118	    await page.goto('/projects');
119	    await expect(page.getByTestId('project-row-1')).toBeVisible();
120	
121	    // "Filter projects by active."
122	    await narrowTo(page, ACTIVE);
123	
124	    // The two active projects (1 and 4) remain; the on-hold (2) and the finished (3) are gone.
125	    await expect(page.getByTestId('project-row-1')).toBeVisible();
126	    await expect(page.getByTestId('project-row-4')).toBeVisible();
127	    await expect(page.getByTestId('project-row-2')).toHaveCount(0);
128	    await expect(page.getByTestId('project-row-3')).toHaveCount(0);
129	    await expect(page.locator('[data-testid^="project-row-"]')).toHaveCount(2);
130	
131	    // Every surviving row genuinely reads as active — not on hold, not finished.
132	    for (const id of [1, 4]) {
133	      const status = page.getByTestId(`project-row-${id}`).getByTestId('project-status');
134	      await expect(status).toContainText(ACTIVE);
135	      await expect(status).not.toContainText(HOLD);
136	      await expect(status).not.toContainText(FINISHED);
137	    }
138	  });
139	
140	  test('switching status follows the chosen status to disjoint sets', async ({ page }) => {
141	    await page.goto('/projects');
142	    await expect(page.getByTestId('project-row-1')).toBeVisible();
143	
144	    // On hold: only project 2 remains.
145	    await narrowTo(page, HOLD);
146	    await expect(page.getByTestId('project-row-2')).toBeVisible();
147	    const onHold = page.getByTestId('project-row-2').getByTestId('project-status');
148	    await expect(onHold).toContainText(HOLD);
149	    await expect(onHold).not.toContainText(ACTIVE);
150	    await expect(onHold).not.toContainText(FINISHED);
151	    await expect(page.getByTestId('project-row-1')).toHaveCount(0);
152	    await expect(page.getByTestId('project-row-3')).toHaveCount(0);
153	    await expect(page.getByTestId('project-row-4')).toHaveCount(0);
154	    await expect(page.locator('[data-testid^="project-row-"]')).toHaveCount(1);
155	
156	    // Finished: the set flips to just project 3 — a different single status, proving the control reads
157	    // the choice rather than always filtering to one.
158	    await narrowTo(page, FINISHED);
159	    await expect(page.getByTestId('project-row-3')).toBeVisible();
160	    const finished = page.getByTestId('project-row-3').getByTestId('project-status');
161	    await expect(finished).toContainText(FINISHED);
162	    await expect(finished).not.toContainText(ACTIVE);
163	    await expect(finished).not.toContainText(HOLD);
164	    await expect(page.getByTestId('project-row-1')).toHaveCount(0);
165	    await expect(page.getByTestId('project-row-2')).toHaveCount(0);
166	    await expect(page.getByTestId('project-row-4')).toHaveCount(0);
167	    await expect(page.locator('[data-testid^="project-row-"]')).toHaveCount(1);
168	  });
169	
170	  test('clearing the filter brings every project back', async ({ page }) => {
171	    await page.goto('/projects');
172	    await expect(page.getByTestId('project-row-1')).toBeVisible();
173	
174	    await narrowTo(page, ACTIVE);
175	    await expect(page.locator('[data-testid^="project-row-"]')).toHaveCount(2);
176	
177	    // Back to all statuses: the on-hold and finished projects return alongside the two active ones.
178	    await showAllStatuses(page);
179	    await expect(page.getByTestId('project-row-1')).toBeVisible();
180	    await expect(page.getByTestId('project-row-2')).toBeVisible();
181	    await expect(page.getByTestId('project-row-3')).toBeVisible();
182	    await expect(page.getByTestId('project-row-4')).toBeVisible();
183	    await expect(page.locator('[data-testid^="project-row-"]')).toHaveCount(4);
184	  });
185	});
