78	// The "show every project" option: an empty value by convention, or an option labelled "all".
79	async function showAll(page: Page): Promise<void> {
80	  const value = await page
81	    .getByTestId('project-tag-filter')
82	    .locator('option')
83	    .evaluateAll((opts) => {
84	      const match = (opts as HTMLOptionElement[]).find(
85	        (o) => o.value === '' || /all/i.test((o.textContent ?? '').trim()),
86	      );
87	      return match ? match.value : null;
88	    });
89	  if (value === null) {
